// Header file: Template Declaration
template <typename T>
class Service {
public:
    void execute(T data); // Implementation hidden
};

// Link optimization: Promise to instantiate Service<int> elsewhere
// Prevents implicit instantiation & bloat in other compilation units.
extern template class Service<int>;

// Source file: Definition & Forced Generation
template <typename T>
void Service<T>::execute(T data) { /* large implementation */ }

// Explicit Instantiation: Code for Service<int> generated ONLY here
template class Service<int>;

// Attempting to use Service<float> will cause a linker error
// unless Service<float> is also explicitly instantiated.
